import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('profetas-menores-miqueas-ii', 'B',
 [dict(t=1767, e=1822, titulo='«¿Quién es como Dios?»', txt='Miqueas quería decir: «¿Quién es como Dios?». Dígame conmigo: ¿quién es como Dios? ¿Habrá alguien como nuestro Dios? […] Si eres falto de amor, él te da un bálsamo en tu corazón y sana tus heridas viejas, que tú te metiste por gusto, por estar escogiendo lo que no es, y te lastimaron. Ahí entra el buen samaritano vendando tus heridas, echándoles vino y aceite, para que haya un bálsamo, para que salgas diferente. ¿En dónde? En el mesón. El mesón es aquí, la iglesia.'),
  dict(t=1925, e=1975, titulo='Honrar a Dios con los bienes', txt='Usted sabe que esta iglesia es diezmadora y ofrendadora. […] Eso repercute en su beneficio, para que podamos reprender al devorador. Ahora, la persona que no da, hermano, tiene un portón abierto, porque ¿cómo va a reprender al devorador? Pero la persona puede decir: «Yo gano lo mismo, hermano». ¿Y qué? Pero se está perdiendo una bendición muy grande. ¿Por qué? Porque nosotros con nuestros bienes honramos a Dios.'),
  dict(t=4265, e=4300, titulo='Traerlos con lazos de amor', txt='Póngalo en las manos de Dios, y Dios, que es bueno, lo va a hacer regresar y lo va a hacer reflexionar. […] Yo, con la palabra profética que Dios me ha dado, que es la Biblia, y que ahí está la autoridad, le hablo a los que están rebeldes, a los jóvenes que están rebeldes, a los que ya no quieren venir a la iglesia: tráelos con lazos de amor o, como dicen en el original, arrástralos.')],
 [dict(t=1195, txt='No es que pasen asistencia en el cielo, pero sí lo toman en cuenta.'),
  dict(t=3320, txt='Huid de las pasiones juveniles. Mira, hermano, no se la lleve de valiente.'),
  dict(t=4615, txt='Trae a tus hijos que dejaron de venir, que están ahí en su casa haciendo nada. Tráelos.')],
 ['¿Qué lugar le das hoy a congregarte con constancia, y qué lo ha estado debilitando?',
  'Si nadie es como Dios, ¿qué herida vieja necesitas poner hoy en sus manos para que la sane?',
  '¿Por quién de tu familia vas a orar esta semana, para que Dios lo traiga con lazos de amor?'])
